import { Component, createContext, createMemo, For, JSX, Match, Show, Switch, useContext } from "solid-js";

//import { FocusManager } from "#core/ui-next/services/focus-manager.js";
import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { ActivatableAudio } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { Header } from "#core/ui-next/components/header.jsx";
import { HeroButton2 } from "#core/ui-next/components/hero-button.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { Tab, TabItemProps } from "#core/ui-next/components/tab.jsx";
import { NestedTooltipContext } from "#core/ui-next/components/tooltip-compat.jsx";
import { ComponentUtilities } from "#core/ui-next/utilities/component-utilities.js";

import style from "#base/ui-next/screens/load-screen/load-screen.scss?url";

//#region Helper Components
const HorizontalDivider: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<div
			{...props}
			class={`load-screen-divider ${props.class}`}
		/>
	);
};

const VerticalDivider: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return <span {...props}>&nbsp;|&nbsp;</span>;
};

const CondensedHeader: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	const header20PxClass = createMemo(() => Layout.pixelsText(20));
	return (
		<div
			{...props}
			class={`uppercase fxs-header pointer-events-auto font-title font-medium ${header20PxClass()} ${
				props.class
			}`}
			data-name="Condensed Header"
		>
			{props.children}
		</div>
	);
};
//#endregion

//#region Info Section
export interface LoadScreenInfoSectionProps {
	name: string;
	attributes: string[];
	description: string;
	abilityType: string;
	abilityName: string;
	abilityDescription: string;
}

const LoadScreenInfoSection: Component<LoadScreenInfoSectionProps> = (props) => {
	function getAttributeIcon(locStr: string) {
		return locStr.replace("LOC_TAG_TRAIT_", "ATTRIBUTE_").replace("_NAME", "");
	}

	return (
		<div class="text-accent-4 load-screen-markup">
			<div class="flex flex-row text-primary-1 -mt-3 items-center">
				<For each={props.attributes}>
					{(attribute, index) => (
						<>
							<Icon
								class="size-8 mr-2"
								name={getAttributeIcon(attribute)}
								context="OUTLINE"
							/>
							<L10n.Stylize
								class="uppercase"
								text={attribute}
							/>
							<Show when={index() < props.attributes.length - 1}>
								<VerticalDivider class="mx-2" />
							</Show>
						</>
					)}
				</For>
			</div>
			<HorizontalDivider class="mb-4 mt-3" />
			<div>
				<L10n.Stylize text={props.description} />
			</div>
			<HorizontalDivider class="my-4" />
			<div class="flex flex-row text-primary-1 flex-wrap justify-start items-start">
				<span class="uppercase">
					<L10n.Compose text={props.abilityType} />
				</span>
				<VerticalDivider class="mx-2" />
				<span class="uppercase text-accent-2">
					<L10n.Compose text={props.abilityName} />
				</span>
			</div>
			<L10n.Stylize
				class="load-screen-ability-desc"
				text={props.abilityDescription}
			/>
		</div>
	);
};
//#endregion

//#region Tips and Hints
export interface LoadScreenTipsAndHintsProps {
	text: string;
	class?: string;
}

const LoadScreenTipsAndHints: Component<LoadScreenTipsAndHintsProps> = (props) => {
	return (
		<div class={`load-screen-tips-and-hints-outer-rect ${props.class}`}>
			<div class="load-screen-tips-and-hints-inner-rect m-0\.5 px-3\.5 pt-2 pb-3\.5">
				<span class="text-tertiary-1 leading-normal uppercase">
					<L10n.Compose text="LOC_LOADING_TIPS_AND_HINTS" />
				</span>
				<span class="text-tertiary-2 leading-none">
					<L10n.Stylize text={props.text} />
				</span>
			</div>
		</div>
	);
};
//#endregion

//#region Unit Info
export interface LoadScreenUnitProps {
	name: string;
	description: string;
	icon: string;
	isAvailable: boolean;
	ageName?: string;
}

const LoadScreenUnits: Component<LoadScreenUnitProps[]> = (props) => {
	return (
		<Show
			when={props.length > 0}
			fallback={<L10n.Compose text="LOC_LOADING_UNIQUE_UNITS_EMPTY" />}
		>
			<For each={props}>
				{(unit, index) => (
					<div
						class="flex flex-col mb-7"
						classList={{ "mb-7": index() < props.length - 1 }}
					>
						<div class="flex flex-row text-accent-4 load-screen-markup">
							<div class="load-screen-icon-slot">
								<div class="load-screen-unit-icon-bg m-3\.5 relative">
									<Icon
										class="absolute inset-0"
										name={unit.icon}
										isUrl={true}
									/>
								</div>
							</div>
							<div class="flex flex-col ml-6 flex-auto">
								<CondensedHeader>
									<L10n.Compose text={unit.name} />
								</CondensedHeader>
								<L10n.Stylize text={unit.description} />
							</div>
						</div>
						<Show when={!unit.isAvailable}>
							<div class="load-screen-not-available-banner flex flex-row mt-2 justify-center items-center">
								<div class="relative flex justify-center items-center">
									<Icon
										class="size-8 absolute"
										name={`url('blp:civ_timetested_100x100')`}
										isUrl={true}
									/>
								</div>
								<span class="uppercase text-accent-2 ml-6 p-1">
									<L10n.Compose
										text="LOC_UI_CREATE_GAME_AVAILABLE_IN_THE_AGE"
										args={[unit.ageName as string]}
									/>
								</span>
							</div>
						</Show>
					</div>
				)}
			</For>
		</Show>
	);
};
//#endregion

//#region Constructible Info
export interface LoadScreenConstructibleProps {
	kind: string;
	name: string;
	description: string;
	icon: string;
	isUniqueQuarter: boolean;
	isAvailable: boolean;
	ageName?: string;
}

const LoadScreenConstructibles: Component<LoadScreenConstructibleProps[]> = (props) => {
	return (
		<Show
			when={props.length > 0}
			fallback={<L10n.Compose text="LOC_LOADING_UNIQUE_BUILDINGS_EMPTY" />}
		>
			<For each={props}>
				{(constructible, index) => (
					<>
						<div
							class="flex flex-row mt-1 text-accent-4 load-screen-markup"
							classList={{
								"mb-7": !constructible.isUniqueQuarter && index() < props.length - 1,
								"ml-7": !constructible.isUniqueQuarter,
							}}
						>
							<Show
								when={constructible.isUniqueQuarter}
								fallback={
									<Icon
										class="load-screen-icon"
										name={constructible.icon}
										isUrl={true}
										context="CIV_BONUS"
									/>
								}
							>
								<div class="load-screen-icon-slot">
									<Icon
										class="m-3\.5 load-screen-icon"
										name={constructible.icon}
										isUrl={true}
										context="CIV_BONUS"
									/>
								</div>
							</Show>
							<div class="flex flex-col ml-6 flex-auto">
								<div class="flex flex-col">
									<Show when={constructible.isUniqueQuarter}>
										<CondensedHeader class="text-accent-2">
											<L10n.Compose text="LOC_LOADING_UNIQUE_QUARTER" />
										</CondensedHeader>
									</Show>
									<CondensedHeader>
										<L10n.Compose text={constructible.name} />
									</CondensedHeader>
								</div>
								<L10n.Stylize text={constructible.description} />
							</div>
						</div>
						<Show
							when={
								!constructible.isAvailable &&
								(constructible.kind == "KIND_QUARTER" || constructible.kind == "KIND_IMPROVEMENT")
							}
						>
							<div class="load-screen-not-available-banner flex flex-row mt-2 justify-center items-center">
								<div class="relative flex justify-center items-center">
									<Icon
										class="size-8 absolute"
										name={`url('blp:civ_timetested_100x100')`}
										isUrl={true}
									/>
								</div>
								<span class="uppercase text-accent-2 ml-6 p-1">
									<L10n.Compose
										text="LOC_UI_CREATE_GAME_AVAILABLE_IN_THE_AGE"
										args={[constructible.ageName as string]}
									/>
								</span>
							</div>
						</Show>
						<Show when={constructible.isUniqueQuarter}>
							<HorizontalDivider class={constructible.isAvailable ? "mt-4 mb-2" : "mt-2 mb-2"} />
						</Show>
					</>
				)}
			</For>
		</Show>
	);
};
//#endregion

//#region Tradition Info
export interface LoadScreenTraditionProps {
	civic: string;
	name: string;
	description: string;
}

const LoadScreenTraditions: Component<LoadScreenTraditionProps[]> = (props) => {
	return (
		<Show
			when={props.length > 0}
			fallback={<L10n.Compose text="LOC_LOADING_TRADITIONS_EMPTY" />}
		>
			<For each={props}>
				{(tradition, index) => (
					<div
						class="flex flex-col ml-3 load-screen-markup text-accent-4"
						classList={{ "mb-9": index() < props.length - 1 }}
					>
						<div class="flex flex-col mb-3 ">
							<div class="flex flex-row mb-1">
								<span>
									<L10n.Compose text="LOC_LOADING_TRADITION_UNLOCKED_WITH" />
									&nbsp;
								</span>
								<span class="text-accent-2 flex-auto">
									<L10n.Compose text={tradition.civic} />
								</span>
							</div>
							<div class="flex flex-row">
								<Icon
									class="load-screen-icon-sm"
									name='url("blp:unlock_tradition")'
									isUrl={true}
								/>
								<div class="flex flex-col ml-6 flex-auto">
									<CondensedHeader>
										<L10n.Compose text={tradition.name} />
									</CondensedHeader>
									<L10n.Stylize text={tradition.description} />
								</div>
							</div>
						</div>
					</div>
				)}
			</For>
		</Show>
	);
};
//#endregion

//#region Memento Info
export interface LoadScreenMementoProps {
	name?: string;
	description?: string;
	flavorText?: string;
	icon?: string;
	isEmpty: boolean;
	isLocked: boolean;
	unlockReason?: string;
}

const LoadScreenMementos: Component<LoadScreenMementoProps[]> = (props) => {
	return (
		<For each={props}>
			{(memento, index) => (
				<div
					class="flex flex-row mb-9 text-accent-4 load-screen-markup"
					classList={{ "mb-9": index() < props.length - 1 }}
				>
					<div class="load-screen-icon-slot">
						<Show
							when={memento.isLocked}
							fallback={
								<Icon
									class="load-screen-icon m-3\.5"
									name={memento.icon}
									isUrl={true}
								/>
							}
						>
							<Icon
								class="load-screen-lock-icon"
								name='url("blp:shell_memento-maj-lock")'
								isUrl={true}
							/>
						</Show>
					</div>
					<div class="flex flex-col ml-6 flex-auto justify-center">
						<Switch
							fallback={
								<>
									<CondensedHeader>
										<L10n.Compose text={memento.name ?? ""} />
									</CondensedHeader>
									<L10n.Stylize text={memento.description ?? ""} />
								</>
							}
						>
							<Match when={memento.isLocked}>
								<div class="text-large font-medium text-tertiary-1">
									<L10n.Compose text={memento.unlockReason ?? ""} />
								</div>
							</Match>
							<Match when={memento.isEmpty}>
								<div class="text-large font-medium text-tertiary-1">
									<L10n.Compose text="LOC_LOADING_MEMENTO_EMPTY" />
								</div>
							</Match>
						</Switch>
					</div>
				</div>
			)}
		</For>
	);
};
//#endregion

//#region Navigation
const Navigation: Component = () => {
	return (
		<>
			<HorizontalDivider />
			<div class="load-screen-pagination">
				<Tab.TabListPips />
			</div>
			<HorizontalDivider />
		</>
	);
};
//#endregion

//#region Progress Bar
interface LoadScreenProgressBarProps {
	progress: number;
}

const LoadScreenProgressBar: Component<LoadScreenProgressBarProps> = (props) => {
	return (
		<div class="load-screen-progress-bar-bg absolute left-0 right-0 top-1\.5">
			<div
				class="load-screen-progress-bar-fill transition-transform duration-1000"
				style={{ transform: `scaleX(${props.progress})` }}
			/>
		</div>
	);
};
//#endregion

//#region Load Screen Context
export interface LoadScreenData {
	tipText: string;
	backgroundImage: string;
	leaderImage: string;
	leaderInfo: LoadScreenInfoSectionProps;
	civInfo: LoadScreenInfoSectionProps;
	unitInfo: LoadScreenUnitProps[];
	constructibleInfo: LoadScreenConstructibleProps[];
	traditionInfo: LoadScreenTraditionProps[];
	mementoInfo: LoadScreenMementoProps[];
}

export interface LoadScreenContextModel {
	data: LoadScreenData | undefined;
	progress: number;
	canBeginGame: boolean;
	startOnCivTab: boolean;
	hideBeginButton: boolean;
	currentTab?: string;
	onBeginGame: () => void;
	onTabChanged: (tab: TabItemProps | undefined) => void;
}

export const LoadScreenContext = createContext<LoadScreenContextModel>();

export function useLoadScreenContext() {
	const context = useContext(LoadScreenContext);

	if (!context) {
		throw new Error("Unable to get load screen context!");
	}

	return context;
}
//#endregion

//region Screen Layout
export interface LoadScreenProps {
	ref?: HTMLDivElement | ((el: HTMLDivElement) => void);
}

export const LoadScreen: Component<LoadScreenProps> = (props) => {
	const model = useLoadScreenContext();
	const defaultTab = createMemo(() => (model.startOnCivTab ? "civ-info" : "leader-info"));
	return (
		<NestedTooltipContext.Provider value={{ disabled: true }}>
			<Panel
				ref={props.ref}
				name="load-screen"
				class="fullscreen load-screen-fade-in"
				id="load-screen"
			>
				<Show when={model.data}>
					<div
						class="absolute inset-0 bg-no-repeat bg-cover bg-center"
						style={{ "background-image": model.data!.backgroundImage }}
					/>
					<div
						data-name="bg-tint"
						class="absolute inset-0 load-screen-bg-tint"
					/>
					<div class="load-screen-above-stage relative h-22">
						<div class="load-screen-above-stage-gradient absolute bottom-0 w-full" />
						<div class="filigree-inner-frame-top-gold absolute -bottom-3 -left-5 -right-5" />
					</div>
					<div
						data-name="bg-filigrees"
						class="absolute inset-0 flex flex-col"
					>
						<div class="load-screen-bg-filigrees-top relative mx-8 mt-8 flex flex-row flex-auto">
							<div class="load-screen-bg-filigree flex-auto" />
							<div class="load-screen-bg-filigree flex-auto -scale-x-100" />
						</div>
						<Filigree.H3
							class="load-screen-filigree-top absolute top-3 left-1\/2"
							style={{ transform: "scaleY(-1) translateX(-50%)" }}
						/>
						<div class="load-screen-bg-filigrees-bottom relative mx-8 mb-8 flex flex-row flex-auto">
							<div class="load-screen-bg-filigree flex-auto -scale-y-100" />
							<div class="load-screen-bg-filigree flex-auto -scale-100" />
						</div>
						<Filigree.H3 class="load-screen-filigree-bottom absolute bottom-3 left-1\/2 -translate-x-1\/2" />
					</div>
					<div
						class="load-screen-stage flex-auto relative bg-no-repeat bg-cover bg-center flex flex-row"
						style={{ "background-image": model.data!.backgroundImage }}
					>
						<div class="load-screen-stage-tint absolute inset-0" />
						<div class="load-screen-stage-fill flex-auto relative" />
						<div class="load-screen-centered-content relative h-full">
							<div class="load-screen-stage-gradient absolute" />
							<div class="load-screen-leader-image-area absolute">
								<div class="load-screen-leader-image-top-gradient absolute" />
								<div
									class="load-screen-leader-image absolute"
									style={{ "background-image": model.data!.leaderImage }}
								/>
								<div class="load-screen-leader-image-bottom-gradient absolute" />
							</div>
							<Tab
								class="load-screen-info absolute inset-0 flex flex-col"
								defaultTab={defaultTab()}
								onTabChanged={model.onTabChanged}
							>
								<Header class="text-2xl font-medium">
									<Tab.Title />
								</Header>
								<HorizontalDivider class="mt-1" />
								<ScrollArea
									class="load-screen-info-scrollable flex-auto pt-3"
									useProxy={true}
									reserveSpace={true}
								>
									<div class="pt-3">
										<Tab.Output />
									</div>
								</ScrollArea>
								<Show
									when={
										model.data!.tipText != "" &&
										["leader-info", "civ-info"].includes(model.currentTab as string)
									}
								>
									<HorizontalDivider class="my-1" />
									<LoadScreenTipsAndHints
										text={model.data!.tipText}
										class="my-2"
									/>
								</Show>
								<HorizontalDivider class="my-1" />
								<Navigation />
								<HorizontalDivider class="my-1" />
								<Filigree.H4
									class={`load-screen-begin-game-button mt-11 ${model.hideBeginButton ? "hidden" : ""}`}
									filigreeClass="mt-5 mx-5"
								>
									<AudioContextProvider
										segment="LoadScreen"
										vars={{ canBeginGame: model.canBeginGame.toString() }}
									>
										<HeroButton2
											class="mx-3 px-8"
											disabled={!model.canBeginGame}
											onActivate={model.onBeginGame}
											classList={{ hidden: model.hideBeginButton }}
											autoFocus={model.canBeginGame}
										>
											<NavHelp
												class="-ml-10 mr-2"
												disabled={!model.canBeginGame}
											/>
											<L10n.Compose text="LOC_LOADING_BEGIN_GAME" />
										</HeroButton2>
									</AudioContextProvider>
								</Filigree.H4>
								<Tab.Item
									name="leader-info"
									title={() => <L10n.Compose text={model.data!.leaderInfo.name} />}
									body={() => <LoadScreenInfoSection {...model.data!.leaderInfo} />}
								/>
								<Tab.Item
									name="civ-info"
									title={() => <L10n.Compose text={model.data!.civInfo.name} />}
									body={() => <LoadScreenInfoSection {...model.data!.civInfo} />}
								/>
								<Tab.Item
									name="constructible-info"
									title={() => <L10n.Compose text="LOC_LOADING_UNIQUE_BUILDINGS" />}
									body={() => <LoadScreenConstructibles {...model.data!.constructibleInfo} />}
								/>
								<Tab.Item
									name="unit-info"
									title={() => <L10n.Compose text="LOC_LOADING_UNIQUE_UNITS" />}
									body={() => <LoadScreenUnits {...model.data!.unitInfo} />}
								/>
								<Tab.Item
									name="tradition-info"
									title={() => <L10n.Compose text="LOC_LOADING_TRADITIONS" />}
									body={() => <LoadScreenTraditions {...model.data!.traditionInfo} />}
								/>
								<Tab.Item
									name="memento-info"
									title={() => <L10n.Compose text="LOC_LOADING_EQUIPPED_MEMENTOS" />}
									body={() => <LoadScreenMementos {...model.data!.mementoInfo} />}
								/>
							</Tab>
						</div>
						<div class="flex-auto" />
					</div>
					<div class="load-screen-below-stage relative h-28">
						<div class="load-screen-below-stage-gradient absolu`te top-0 w-full" />
						<div class="filigree-inner-frame-top-gold absolute top-0 -left-5 -right-5" />
						<LoadScreenProgressBar progress={model.progress} />
					</div>
				</Show>
			</Panel>
		</NestedTooltipContext.Provider>
	);
};
//#endregion Screen Layout

ComponentUtilities.loadStyles(style);
